const redeliverWebhookDelivery = `-- name: RedeliverWebhookDelivery :execrows
UPDATE webhook_deliveries
SET state = 'pending', attempts = 0, next_attempt_at = NOW(), error = NULL, actor_id = $1
WHERE webhook_id = $2 AND id = $3 AND state <> 'pending'
`

type RedeliverWebhookDeliveryParams struct {
	ActorID   pgtype.UUID `json:"actor_id"`
	WebhookID pgtype.UUID `json:"webhook_id"`
	ID        pgtype.UUID `json:"id"`
}

// The same delivery again, its retries started over; not while it waits.
func (q *Queries) RedeliverWebhookDelivery(ctx context.Context, arg RedeliverWebhookDeliveryParams) (int64, error) {
	result, err := q.db.Exec(ctx, redeliverWebhookDelivery, arg.ActorID, arg.WebhookID, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

